  sidequests: [
    { id: "sidequest-child-trade", name: "From the Weird Egg to Zelda's Letter", summary: "Hatch Malon's egg, wake her father, and meet Princess Zelda.",
      steps: [
        "Get the Weird Egg from Malon on the castle road.",
        "Wait for dawn; the egg hatches into a Chicken.",
        "Wake Talon by the castle moat with the Chicken, then sneak into the castle grounds by day and meet Zelda for her letter.",
        "Show Zelda's Letter to the guard at the Death Mountain gate in Kakariko; the gate opens and so does the Happy Mask Shop."
      ],
      rewards: ["Zelda's Letter", "Zelda's Lullaby", "Access to Death Mountain Trail and the Happy Mask Shop"] },
    { id: "sidequest-mask-shop", name: "The Happy Mask Shop", summary: "Borrow masks, sell them to the people who want them, and pay the shop back to unlock the next mask.",
      steps: [
        "Keaton Mask: sell it to the Kakariko gate guard for 15 Rupees; pay back 10.",
        "Skull Mask: wear it at the Forest Stage, then sell it to the Skull Kid in the Lost Woods for 10 Rupees; pay back 20.",
        "Spooky Mask: sell it to the boy in the Kakariko Graveyard by day for 30 Rupees; pay back 30.",
        "Bunny Hood (after all 3 Spiritual Stones): sell it to the Running Man in Hyrule Field, who fills your wallet; pay back 50.",
        "Borrow the Mask of Truth and wear it at the Forest Stage and to the Gossip Stones. The Goron, Zora and Gerudo Masks are now free to borrow too."
      ],
      rewards: ["Deku Stick capacity upgrade", "Deku Nut capacity upgrade", "Mask of Truth", "A full wallet from the Running Man"] },
    { id: "sidequest-adult-trade", name: "Biggoron's Sword", summary: "Trade a Pocket Egg up through 11 items to get the strongest sword in the game.",
      steps: [
        "Get the Pocket Egg from the Cucco Lady by day and let it hatch at dawn into the Pocket Cucco.",
        "Wake Talon in Kakariko with it, then trade it to the Cucco Lady for Cojiro.",
        "Trade Cojiro in the Lost Woods for the Odd Mushroom, then take it to the old woman behind the Kakariko Potion Shop within 3 minutes for the Odd Poultice.",
        "Trade the Odd Poultice to Fado in the Lost Woods for the Poacher's Saw, and the saw to the head carpenter in Gerudo Valley for the Broken Goron's Sword.",
        "Biggoron trades the sword for a Prescription. King Zora, once thawed, trades it for the Eyeball Frog (3 minutes), and the Lake Hylia professor turns the frog into the World's Finest Eye Drops (4 minutes).",
        "Deliver the drops to Biggoron for the Biggoron Receipt, wait 3 days, and claim Biggoron's Sword."
      ],
      rewards: ["Biggoron's Sword"] },
    { id: "sidequest-big-poes", name: "The Big Poe hunt", summary: "Catch the 10 Big Poes in Hyrule Field on Epona and sell their souls to the Poe Collector.",
      steps: [
        "Bring Epona, the Fairy Bow and every empty Bottle you have.",
        "Ride over each of the 10 spots; shoot each Big Poe twice and catch its soul in a Bottle.",
        "Sell the souls to the Poe Collector in the old Guard House at the ruined Market entrance, 50 Rupees each.",
        "At 10 souls he gives you a Bottle."
      ],
      rewards: ["Bottle", "50 Rupees per Big Poe"] },
    { id: "sidequest-epona", name: "Winning Epona", summary: "Learn Epona's Song as a child and win Epona from Ingo as an adult.",
      steps: [
        "As a child, learn Epona's Song from Malon at Lon Lon Ranch by day.",
        "As an adult, pay Ingo 10 Rupees to ride and play Epona's Song to call her.",
        "Race Ingo for a 50-Rupee bet and win; win the rematch to take Epona.",
        "Ingo shuts the gate; jump the fence on Epona to escape."
      ],
      rewards: ["Epona", "Malon's obstacle course, whose prize is a cow for Link's House"] },
    { id: "sidequest-lost-dog", name: "The lost dog", summary: "Return a woman's runaway puppy in the Market at night.",
      steps: [
        "Enter the Market at night as a child.",
        "Find the white puppy and touch it so it follows you; keep other dogs away.",
        "Lead it into the Back Alley and through the door on the left that opens only at night."
      ],
      rewards: ["Piece of Heart"] },
    { id: "sidequest-cuccos", name: "The Cucco Lady's Cuccos", summary: "Return 7 loose Cuccos to their pen in Kakariko Village by day.",
      steps: [
        "Find the Cuccos around the village, including one in a crate and 2 in the fenced yard in the northeast corner.",
        "Carry or throw each one into the pen by the Graveyard path.",
        "Talk to the Cucco Lady once all 7 are in."
      ],
      rewards: ["Bottle"] },
    { id: "sidequest-skulltula-house", name: "The House of Skulltula", summary: "Lift the curse on a Kakariko family by collecting Gold Skulltula Tokens.",
      steps: [
        "Collect tokens from the 100 Gold Skulltulas.",
        "Visit the House of Skulltula at 10, 20, 30, 40, 50 and 100 tokens and talk to the family member who has turned back to normal."
      ],
      rewards: ["Adult's Wallet", "Echo Gem", "Giant's Wallet", "10 Bombchus", "Piece of Heart", "A repeatable Huge Rupee"] },
    { id: "sidequest-scarecrow", name: "The Scarecrow's Song", summary: "Compose a tune for the Lake Hylia scarecrows to get a portable Hookshot target.",
      steps: [
        "As a child, talk to Bonooru, the lower of the 2 scarecrows near the Lakeside Laboratory, and play any 8 notes. Write them down.",
        "As an adult, play the same 8 notes to Bonooru again.",
        "Play the song wherever Navi turns green to call Pierre, then Hookshot to him."
      ],
      rewards: ["Scarecrow's Song", "Access to the Fire Temple and Dodongo's Cavern scarecrow Gold Skulltulas and the Fire Temple scarecrow chest"] },
    { id: "sidequest-magic-beans", name: "Magic Beans", summary: "Plant beans in the 10 patches of soft soil as a child and ride the plants as an adult.",
      steps: [
        "Buy beans from the salesman at Zora's River; the price rises by 10 Rupees with each one.",
        "Plant 1 bean in each patch of soft soil as a child; Bolero of Fire and Requiem of Spirit reach the crater and desert patches.",
        "As an adult, step onto the leaf of each grown plant to ride it."
      ],
      rewards: ["Access to 4 Pieces of Heart and 2 Gold Skulltulas", "Shortcuts on Death Mountain and in the Lost Woods"] },
    { id: "sidequest-carpenters", name: "The captured carpenters", summary: "Free the 4 carpenters held in Gerudo's Fortress.",
      steps: [
        "Cross Gerudo Valley as an adult (Epona or the Longshot) and talk to the head carpenter by his tent.",
        "Sneak into Gerudo's Fortress. If a guard sees you, you land in a cell; Hookshot the wooden overhang by the window to get out.",
        "Find each carpenter's cell and defeat the Gerudo Thief who guards it to get the key.",
        "With all 4 free, the Gerudo leader gives you Gerudo Pass."
      ],
      rewards: ["Gerudo Pass", "Access to the Mirage Desert, the Gerudo Proving Grounds and horseback archery"] },
    { id: "sidequest-gossip-stones", name: "Gossip Stones", summary: "Stone statues around Hyrule that give hints and fairies.",
      steps: [
        "Wear the Mask of Truth and talk to a Gossip Stone to hear its hint.",
        "Play Zelda's Lullaby, Epona's Song, the Sun's Song or the Song of Time next to one for a small healing fairy you can bottle; the Song of Storms brings a large fairy.",
        "Strike one with your sword to learn the time of day."
      ],
      rewards: ["Hints", "Fairies"] }
  ],

